import{_ as e,a0 as o,w as l,s as r,ao as u,I as p,x as n,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何不重裝修復損壞的 Ubuntu 系統 | LCTT x X-CMD","titleTemplate":false,"description":"如何不重裝修復損壞的 Ubuntu 系統 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何不重裝修復損壞的 Ubuntu 系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何不重裝修復損壞的 Ubuntu 系統 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181205 How To Fix Broken Ubuntu OS Without Reinstalling It","title":"如何不重裝修復損壞的 Ubuntu 系統","tag":"201812","desc":""},"relativePath":"201812/20181205 How To Fix Broken Ubuntu OS Without Reinstalling It.md","filePath":"[post].md"}'),d={name:"201812/20181205 How To Fix Broken Ubuntu OS Without Reinstalling It.md"};function b(g,t,k,f,T,h){const s=o("Link");return l(),r("div",null,[t[20]||(t[20]=u('<h1 id="如何不重裝修復損壞的-ubuntu-系統" tabindex="-1">如何不重裝修復損壞的 Ubuntu 系統 <a class="header-anchor" href="#如何不重裝修復損壞的-ubuntu-系統" aria-label="Permalink to “如何不重裝修復損壞的 Ubuntu 系統”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/Fix-Broken-Ubuntu-OS-720x340.jpg" alt=""></p><p>今天，我在升級我的 Ubuntu 18.04 LTS 系統。不幸的是，在更新 Ubuntu 時中途斷電，系統關機。電源恢復後，我再次啓動系統。在登錄頁面輸入密碼後，它變成空白並且沒有響應。鍵盤和鼠標也沒有作用。我只看到一個空白的屏幕！值得慶幸的是，它只是一台測試機，並且沒有重要的數據。我可以直接擦除整個系統然後重新安裝。但是，我不想這樣做。由於我沒有什麼可失去的，我只是想不重裝修復我損壞的 Ubuntu 系統，並且我成功了！如果你發現自己處於像我這樣的境地，不要驚慌。這個簡短的教程描述瞭如何在不丟失數據的情況下輕鬆修復損壞的 Ubuntu 系統，而無需重新安裝。</p><h3 id="修復損壞的-ubuntu-系統" tabindex="-1">修復損壞的 Ubuntu 系統 <a class="header-anchor" href="#修復損壞的-ubuntu-系統" aria-label="Permalink to “修復損壞的 Ubuntu 系統”">​</a></h3><p>首先，嘗試使用 live cd 登錄並<strong>在外部驅動器中備份數據</strong>。以防這個方法沒用，你仍然可以獲取數據並重新安裝系統！</p>',5)),p("p",null,[t[1]||(t[1]=n("在登錄頁上，按下 ",-1)),t[2]||(t[2]=p("code",null,"CTRL+ALT+F1",-1)),t[3]||(t[3]=n(" 切換到 tty1。你可以在",-1)),i(s,{href:"https://www.ostechnix.com/how-to-switch-between-ttys-without-using-function-keys-in-linux/"},{default:a(()=>[...t[0]||(t[0]=[n("此處",-1)])]),_:1}),t[4]||(t[4]=n("瞭解有關在 TTY 之間切換的更多信息。",-1))]),t[21]||(t[21]=u(`<p>現在，逐個輸入以下命令來修復損壞的 Ubuntu Linux。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rm /var/lib/apt/lists/lock</span></span>
<span class="line"><span>$ sudo rm /var/lib/dpkg/lock</span></span>
<span class="line"><span>$ sudo rm /var/lib/dpkg/lock-frontend</span></span>
<span class="line"><span>$ sudo dpkg --configure -a</span></span>
<span class="line"><span>$ sudo apt clean</span></span>
<span class="line"><span>$ sudo apt update --fix-missing</span></span>
<span class="line"><span>$ sudo apt install -f</span></span>
<span class="line"><span>$ sudo dpkg --configure -a</span></span>
<span class="line"><span>$ sudo apt upgrade</span></span>
<span class="line"><span>$ sudo apt dist-upgrade</span></span></code></pre></div><p>最後，使用命令重啓系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo reboot</span></span></code></pre></div><p>你現在可以像往常一樣登錄到你的 Ubuntu 系統。</p><p>我做完這些步驟後，我 Ubuntu 18.04 測試系統中的所有數據都還在，一切都之前的一樣。此方法可能不適用於所有人。但是，這個小小的技巧對我有用，並且比重裝節省了一些時間。如果你瞭解其他更好的方法，請在評論區告訴我。我也會在本指南中添加它們。</p><p>這是這些了。希望這篇文章有用。</p><p>還有更多好東西。敬請關注！</p><p>乾杯!</p><hr>`,10)),p("p",null,[t[6]||(t[6]=n("via: ",-1)),i(s,{href:"https://www.ostechnix.com/how-to-fix-broken-ubuntu-os-without-reinstalling-it/"},{default:a(()=>[...t[5]||(t[5]=[n("https://www.ostechnix.com/how-to-fix-broken-ubuntu-os-without-reinstalling-it/",-1)])]),_:1})]),p("p",null,[t[11]||(t[11]=n("作者：",-1)),i(s,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...t[7]||(t[7]=[n("SK",-1)])]),_:1}),t[12]||(t[12]=n(" 選題：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[8]||(t[8]=[n("lujun9972",-1)])]),_:1}),t[13]||(t[13]=n(" 譯者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:a(()=>[...t[9]||(t[9]=[n("geekpi",-1)])]),_:1}),t[14]||(t[14]=n(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:a(()=>[...t[10]||(t[10]=[n("wxy",-1)])]),_:1})]),p("p",null,[t[17]||(t[17]=n("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[15]||(t[15]=[n("LCTT",-1)])]),_:1}),t[18]||(t[18]=n(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:a(()=>[...t[16]||(t[16]=[n("Linux中國",-1)])]),_:1}),t[19]||(t[19]=n(" 榮譽推出",-1))])])}const C=e(d,[["render",b]]);export{w as __pageData,C as default};
